-- Tetra Light for Neovim: aether.nvim with Tetra's palette and syntax colours.
-- Generated by ~/.config/omarchy/tetra/generate; edit that, not this file.
local r = {
	tag = "#1c84bf",
	special = "#d0ba91",
	operator = "#ce6a3f",
	error = "#db3b4d",
	vcs_added = "#438b47",
	vcs_modified = "#9251e9",
	vcs_removed = "#fc486a",
}

return {
	{
		"bjarneo/aether.nvim",
		branch = "v3",
		name = "aether",
		priority = 1000,
		opts = {
			colors = {
				bg = "#f6f6f6",
				dark_bg = "#f5f5f5",
				darker_bg = "#f0f0f0",
				lighter_bg = "#ededed",
				fg = "#3b3b3b",
				dark_fg = "#565656",
				light_fg = "#363636",
				bright_fg = "#303030",
				muted = "#91a0c0",
				red = "#c1465e",
				yellow = "#7f6918",
				orange = "#d56800",
				green = "#4f7923",
				cyan = "#336f6d",
				blue = "#2272c2",
				magenta = "#904bb6",
				brown = "#ae7829",
				bright_red = "#ec5e79",
				bright_yellow = "#9a7c00",
				bright_green = "#618f34",
				bright_cyan = "#3b8683",
				bright_blue = "#0088f3",
				bright_magenta = "#bc1eff",
				accent = "#e6b450",
				cursor = "#303030",
				foreground = "#3b3b3b",
				background = "#f6f6f6",
				selection = "#e7ebf3",
				selection_foreground = "#303030",
				selection_background = "#e7ebf3",
			},
			styles = { comments = { italic = true }, keywords = {}, functions = {}, variables = {} },
			on_colors = function(c)
				local blend = require("aether.utils").blend_bg
				c.git = { add = r.vcs_added, delete = r.vcs_removed, change = r.vcs_modified, ignore = c.muted }
				c.diff.add = blend(r.vcs_added, 0.25)
				c.diff.delete = blend(r.vcs_removed, 0.25)
				c.error, c.warning, c.info, c.hint, c.todo = r.error, c.orange, r.tag, c.bright_cyan, c.bright_red
				-- terminal slots 0, 7, 8 and 15 as foot and Ghostty have them
				c.terminal.black, c.terminal.white = c.bg, c.fg
				c.terminal.black_bright, c.terminal.white_bright = c.muted, c.bright_fg
			end,
			on_highlights = function(hl, c)
				for group, spec in pairs({
					Comment = { fg = c.muted, italic = true },
					Constant = { fg = c.bright_magenta },
					String = { fg = c.bright_green },
					Character = { fg = c.bright_green },
					Number = { fg = c.bright_magenta },
					Boolean = { fg = c.bright_magenta },
					Float = { fg = c.bright_magenta },
					Identifier = { fg = c.bright_blue },
					Function = { fg = c.bright_yellow },
					Statement = { fg = c.orange },
					Conditional = { fg = c.orange },
					Repeat = { fg = c.orange },
					Label = { fg = c.orange },
					Keyword = { fg = c.orange },
					Exception = { fg = c.bright_red },
					Operator = { fg = r.operator },
					PreProc = { fg = c.accent },
					Include = { fg = c.orange },
					Define = { fg = c.orange },
					Macro = { fg = c.accent },
					Type = { fg = c.bright_blue },
					StorageClass = { fg = c.orange },
					Structure = { fg = r.special },
					Typedef = { fg = c.bright_blue },
					Special = { fg = c.accent },
					SpecialChar = { fg = r.special },
					Tag = { fg = r.tag },
					Delimiter = { fg = r.special },
					Title = { fg = c.orange },
					Directory = { fg = c.bright_yellow },
					Underlined = { sp = r.tag, underline = true },
					Error = { fg = c.bg, bg = r.error },
					ErrorMsg = { fg = r.error },
					WarningMsg = { fg = c.orange },
					Todo = { fg = c.bright_red },
					Added = { fg = r.vcs_added },
					Changed = { fg = r.vcs_modified },
					Removed = { fg = r.vcs_removed },
					GitSignsDelete = { fg = r.vcs_removed },
					NeoTreeGitDeleted = { fg = r.vcs_removed },
					NvimTreeGitDeleted = { fg = r.vcs_removed },
					DiffviewStatusDeleted = { fg = r.vcs_removed },
					DiagnosticError = { fg = r.error },
					DiagnosticWarn = { fg = c.orange },
					DiagnosticInfo = { fg = r.tag },
					DiagnosticHint = { fg = c.bright_cyan },
					["@comment.error"] = { fg = r.error },
					["@comment.warning"] = { fg = c.orange },
					["@comment.todo"] = { fg = c.bright_red },
					["@constructor"] = { fg = c.accent },
					["@constructor.tsx"] = { fg = c.accent },
					["@keyword"] = { fg = c.orange },
					["@keyword.function"] = { fg = c.orange },
					["@label"] = { fg = c.orange },
					["@module"] = { fg = c.bright_yellow },
					["@module.builtin"] = { fg = c.bright_yellow },
					["@operator"] = { fg = r.operator },
					["@property"] = { fg = r.tag },
					["@punctuation.bracket"] = { fg = r.special },
					["@punctuation.delimiter"] = { fg = r.special },
					["@punctuation.special"] = { fg = r.special },
					["@string.documentation"] = { fg = c.bright_green },
					["@string.escape"] = { fg = r.special },
					["@string.regexp"] = { fg = c.bright_cyan },
					["@tag"] = { fg = c.orange },
					["@tag.attribute"] = { fg = c.bright_blue },
					["@tag.delimiter.tsx"] = { fg = r.special },
					["@tag.tsx"] = { fg = c.orange },
					["@tag.javascript"] = { fg = c.orange },
					["@type.builtin"] = { fg = c.bright_blue },
					["@variable"] = { fg = c.fg },
					["@variable.builtin"] = { fg = c.bright_yellow },
					["@variable.member"] = { fg = r.tag },
					["@variable.parameter"] = { fg = c.fg },
					["@variable.parameter.builtin"] = { fg = c.fg },
					["@markup.heading"] = { fg = c.orange },
					["@lsp.type.class"] = { link = "@type" },
					["@lsp.type.interface"] = { link = "@type" },
					["@lsp.type.struct"] = { link = "@variable.member" },
				}) do
					hl[group] = spec
				end
			end,
		},
	},
	{
		"LazyVim/LazyVim",
		opts = {
			colorscheme = "aether",
		},
	},
}
